SELECT 'gongkao', '功能规律概述', 'kp-xc-tutui-func-overview', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"功能规律概述"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"识别特征：","marks":[{"type":"bold"}]},{"type":"text","text":"图形中出现小圆点、线段、箭头等「功能元素」。约占图形推理的 3%。功能元素不是用来数数的，而是用来「标记位置」的。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、包含的子类"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"功能点：标记位置（上下/左右/内外）、标记样式（交点/顶点/线）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"功能线：头尾方向（平行/垂直）、连接最长最短线"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"功能箭头：指向方向、与图形某边的关系"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、核心思路"}]},{"type":"paragraph","content":[{"type":"text","text":"功能元素的本质是「标记」—— 它标记了图形中的某个特殊位置或关系。解题时不要去数功能元素，而要思考「它标记了什么」。"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"学习建议：","marks":[{"type":"bold"}]},{"type":"text","text":"功能规律考频较低，但一旦出现往往是区分题。掌握「功能元素 = 标记」的核心思路即可。"}]}]}]}$$ AS jsonb), NULL, '功能规律概述：功能点、功能线、功能箭头的识别特征与核心思路。', category_node.id, CAST('["图形推理", "功能规律", "概述"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_logic_figure_reasoning_functional", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
